fn format_sysv_line(&self, sum: &str, sz: usize, filename: Option<&OsStr>) -> Vec<u8> {
    let body = format!("{} {}", sum.parse::<u16>().unwrap(), self.legacy_blocks(sz));
    match filename {
        Some(f) => {
            let mut out = body.into_bytes();
            out.push(b' ');
            out.extend_from_slice(&self.filename_bytes(f));
            out
        }
        None => body.into_bytes(),
    }
}

fn format_bsd_line(&self, sum: &str, sz: usize, filename: Option<&OsStr>) -> Vec<u8> {
    let bsd_width = 5;
    let body = format!(
        "{:0bsd_width$} {:bsd_width$}",
        sum.parse::<u16>().unwrap(),
        self.legacy_blocks(sz)
    );
    match filename {
        Some(f) => {
            let mut out = body.into_bytes();
            out.push(b' ');
            out.extend_from_slice(&self.filename_bytes(f));
            out
        }
        None => body.into_bytes(),
    }
}

fn format_crc_line(&self, sum: &str, sz: usize, filename: Option<&OsStr>) -> Vec<u8> {
    let mut out = format!("{sum} {sz}").into_bytes();
    if let Some(f) = filename {
        out.push(b' ');
        out.extend_from_slice(&self.filename_bytes(f));
    }
    out
}

fn filename_bytes(&self, filename: &OsStr) -> Vec<u8> {
    os_str_as_bytes(filename).unwrap_or_else(|_| filename.to_string_lossy().into_owned().into_bytes())
}

fn format_tagged_digest(&self, algo: &str, sum: &str, filename: &OsStr) -> Vec<u8> {
    if self.tag {
        self.format_generic_line(algo, sum, filename)
    } else {
        self.format_untagged_digest(sum, filename)
    }
}

fn format_untagged_digest(&self, sum: &str, filename: &OsStr) -> Vec<u8> {
    let prefix = self.prefix_for_binary();
    let mut out = format!("{sum} {prefix}").into_bytes();
    out.extend_from_slice(&self.filename_bytes(filename));
    out
}

fn format_blake2_tagged(&self, sum: &str, filename: &OsStr) -> Vec<u8> {
    if let Some(length) = self.length {
        let mut out = format!("BLAKE2b-{} (", length * 8).into_bytes();
        out.extend_from_slice(&self.filename_bytes(filename));
        out.extend_from_slice(format!(") = {sum}").as_bytes());
        out
    } else if self.tag {
        let mut out = b"BLAKE2b (".to_vec();
        out.extend_from_slice(&self.filename_bytes(filename));
        out.extend_from_slice(format!(") = {sum}").as_bytes());
        out
    } else {
        self.format_untagged_digest(sum, filename)
    }
}

