fn choose_digest_output(&self, algo: &str, sum: &str, sz: usize, filename: &OsStr, not_file: bool) -> Vec<u8> {
    if algo == ALGORITHM_OPTIONS_BLAKE2B && self.tag {
        return self.format_blake2_tagged(sum, filename);
    }
    let named = if self.should_emit_filename(not_file) {
        Some(filename)
    } else {
        None
    };
    match (algo, named) {
        (ALGORITHM_OPTIONS_SYSV, path) => self.format_sysv_line(sum, sz, path),
        (ALGORITHM_OPTIONS_BSD, path) => self.format_bsd_line(sum, sz, path),
        (ALGORITHM_OPTIONS_CRC, path) => self.format_crc_line(sum, sz, path),
        (_, Some(path)) if self.tag => self.format_tagged_digest(algo, sum, path),
        (_, Some(path)) => self.format_untagged_digest(sum, path),
        (_, None) if self.tag => self.format_tagged_digest(algo, sum, filename),
        (_, None) => self.format_untagged_digest(sum, filename),
    }
}

